INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920101', '910101', 'Why Data Privacy Matters in Schools', 'text', '<h3>Every record is a person</h3>\n <p>Schools hold some of the most sensitive information in any organisation: birth dates, home addresses, medical notes, disciplinary records, and the learning difficulties of minors. A single leaked class list can expose hundreds of families.</p>\n <p>The Data Privacy Act does not exist to stop staff from doing their work. It exists so that information is collected for a declared reason, kept only as long as needed, and seen only by people who need it.</p>\n <h3>What goes wrong in practice</h3>\n <ul>\n   <li>Class lists shared in group chats that include guardians of other students.</li>\n   <li>Spreadsheets downloaded to personal laptops for weekend work.</li>\n   <li>Old enrollment forms kept in a cabinet years after the records were closed.</li>\n </ul>\n <p>None of these start with bad intent. All of them are reportable incidents.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920102', '910101', 'The Three Core Principles', 'text', '<h3>Transparency, legitimate purpose, proportionality</h3>\n <p>Almost every compliance question you will face resolves into these three tests.</p>\n <ul>\n   <li><strong>Transparency.</strong> The person knows what is collected, why, who receives it, and how long it is kept.</li>\n   <li><strong>Legitimate purpose.</strong> The reason is tied to a declared function such as enrollment, payroll, or academic records, not curiosity.</li>\n   <li><strong>Proportionality.</strong> You collect only what that purpose needs. A contact number yes, a copy of a government ID usually not.</li>\n </ul>\n <p>A useful test before pressing send: could you explain this use to the student or parent without hesitating? If not, the purpose is not clear enough to rely on.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920103', '910101', 'Who Is Accountable: Controllers, Processors, and the DPO', 'text', '<h3>Three roles, three kinds of responsibility</h3>\n <p>The <strong>personal information controller</strong> decides what data is collected and why. In a school that is the institution itself, not the individual teacher.</p>\n <p>The <strong>personal information processor</strong> handles data on the controller instructions. A cloud grading platform, a payroll bureau, or an external printing house is a processor, and each one needs a written agreement before any data is shared.</p>\n <p>The <strong>Data Protection Officer</strong> is the internal point of accountability: registering processing activities, reviewing contracts, receiving complaints, and notifying the regulator when a breach meets the threshold.</p>\n <p>If you are unsure whether a request needs DPO review, it does. Escalation is free. A wrongful disclosure is not.</p>', NULL, '3', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920104', '910102', 'Collect Only What You Need', 'text', '<h3>Design forms backwards</h3>\n <p>Most over-collection happens on paper. A form asks for a home address, a second contact number, and a copy of a certificate because it always has, not because anyone uses those fields.</p>\n <ul>\n   <li>For every field, name the decision it supports. No decision, no field.</li>\n   <li>Keep sensitive fields optional unless a specific process requires them.</li>\n   <li>Replace document copies with verification: record that an ID was seen, not the ID itself.</li>\n </ul>\n <h3>Retention is part of collection</h3>\n <p>Decide the disposal date when the form is created. Data that has no owner and no expiry date is data that will still be on a shared drive in ten years.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920105', '910102', 'Securing Devices, Files, and Shared Drives', 'video', NULL, 'https://www.youtube.com/embed/1Y9d3lR6Qm4', '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920106', '910102', 'Responding to a Suspected Data Breach', 'text', '<h3>The first hour matters most</h3>\n <p>A breach is any accidental or unlawful loss, alteration, or disclosure of personal data. It includes sending an email to the wrong parent, not only an attack from outside.</p>\n <ol>\n   <li><strong>Contain.</strong> Recall the message, revoke the shared link, or disconnect the device. Do not investigate first.</li>\n   <li><strong>Report.</strong> Tell the DPO immediately, in writing, with what was exposed and to whom.</li>\n   <li><strong>Do not negotiate quietly.</strong> Informal settlements with affected families create a second, larger problem.</li>\n </ol>\n <p>The regulator expects notice within 72 hours where the breach meets the reporting threshold. That clock starts when the incident happens, not when the investigation finishes.</p>', NULL, '3', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920107', '910103', 'The Eight Rights at a Glance', 'text', '<h3>What a data subject can ask for</h3>\n <p>Being informed, objecting, accessing, rectifying, erasing or blocking, claiming damages, filing a complaint, and data portability. In a school context, most requests you will meet are access, correction, and objection to a specific disclosure.</p>\n <p>The practical rule: a request does not need to cite the law or use the word request. A parent asking what information the school holds about their child is exercising a right, and the response time starts immediately.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920108', '910103', 'Processing Access and Correction Requests', 'text', '<h3>A repeatable process</h3>\n <ul>\n   <li>Verify identity before releasing anything. Confirm through an existing channel, not through the address in the request.</li>\n   <li>Confirm authority: a guardian may act for a minor, but a relative may not act for an adult employee.</li>\n   <li>Separate the personal data of the requester from the personal data of other people, which must be redacted.</li>\n   <li>Record the decision, the date, and who approved it.</li>\n </ul>\n <p>Correction requests are not edits on request. Validate against the source document, then correct the system of record and any downstream copy, including exports already shared.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920109', '910104', 'From Job Description to Objectives', 'text', '<h3>The job description is a map, not a target</h3>\n <p>A job description lists responsibilities. Objectives translate two or three of those responsibilities into measurable outcomes for the cycle.</p>\n <p>Choose the responsibilities where performance genuinely varies and where improvement matters this year. Copying every line of the description produces a list nobody reviews in December.</p>\n <p>Three to five objectives is the working range. More than that and priorities stop being priorities.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920110', '910104', 'Writing Measurable Goals', 'text', '<h3>Specific enough to disagree with</h3>\n <p>A well-written objective should be precise enough that two people could look at the result and reach the same conclusion.</p>\n <ul>\n   <li><strong>Weak:</strong> Improve student records turnaround.</li>\n   <li><strong>Better:</strong> Release corrected enrollment records within three working days of a validated request, for at least 90 percent of requests.</li>\n </ul>\n <p>Name the measure, the threshold, and the period. When an objective cannot be measured numerically, name the evidence that will be reviewed instead.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920111', '910105', 'The SBI Feedback Model', 'text', '<h3>Situation, Behaviour, Impact</h3>\n <p>Feedback that survives the conversation is specific, timely, and about behaviour rather than character.</p>\n <ul>\n   <li><strong>Situation.</strong> In the enrollment briefing on Tuesday, when the guardian asked about the deadline.</li>\n   <li><strong>Behaviour.</strong> You read the dates from last year handout.</li>\n   <li><strong>Impact.</strong> Three families left with the wrong deadline and two came back angry.</li>\n </ul>\n <p>Say it within 48 hours, in private, and end by asking what will change next time. Praise works the same way: vague praise teaches nothing.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920112', '910105', 'Documenting Performance Fairly', 'text', '<h3>What a reviewer will look for</h3>\n <p>Documentation should let a third party reconstruct why a conclusion was reached. That means dated examples, not adjectives.</p>\n <ul>\n   <li>Record the observation, not the personality. The report was late twice is defensible. The report is careless is not.</li>\n   <li>Record positive outcomes with the same discipline as concerns.</li>\n   <li>Share the note with the employee. Undocumented criticism is the single most common cause of a successful appeal.</li>\n </ul>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920113', '910106', 'Preparing for the Review Meeting', 'text', '<h3>No surprises</h3>\n <p>If the appraisal meeting is the first time an employee hears a concern, the process has already failed. The meeting summarises a story both people already know.</p>\n <ul>\n   <li>Send the self-assessment and the draft rating before the meeting.</li>\n   <li>Bring the evidence: objectives, dated examples, and delivery records.</li>\n   <li>Separate the rating conversation from the development conversation. Mixing them makes both worse.</li>\n </ul>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920114', '910106', 'Handling Disagreement and Appeals', 'text', '<h3>Disagreement is information</h3>\n <p>When an employee rejects a rating, ask what evidence they think is missing. Sometimes they are right, and correcting the record early is cheaper than defending it later.</p>\n <p>If you still disagree, state the evidence standard, explain how the rating was derived, and confirm the appeal route in writing. Calm process beats persuasive argument.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920115', '910107', 'Needs Analysis in Five Questions', 'text', '<h3>Do not design a course until you can answer these</h3>\n <ol>\n   <li>Who is not performing, and how do we know?</li>\n   <li>Is the gap caused by knowledge, skill, environment, or motivation?</li>\n   <li>What would correct performance look like on a normal Tuesday?</li>\n   <li>What already exists that could close the gap?</li>\n   <li>How will we know it worked, three months later?</li>\n </ol>\n <p>If the honest answer to any question is we were told to run a training, the request is not yet a learning problem. Training fixes knowledge and skill gaps. It cannot fix a broken process.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920116', '910107', 'Writing Learning Objectives', 'text', '<h3>Observable verbs only</h3>\n <p>An objective describes what the learner will be able to do after the course, in terms someone could watch or mark.</p>\n <ul>\n   <li><strong>Not measurable:</strong> Understand the retention schedule.</li>\n   <li><strong>Measurable:</strong> Classify ten sample documents using the retention schedule, with at least eight correct.</li>\n </ul>\n <p>Keep one behaviour per objective. If the sentence needs and, it is usually two objectives competing for attention.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920117', '910108', 'Sequencing Content for Retention', 'text', '<h3>Cognitive load is the budget</h3>\n <p>Working memory holds roughly four new items. A lesson that introduces twelve concepts in one screen is not thorough, it is unlearnable.</p>\n <ul>\n   <li>Introduce one idea per screen, then let the learner use it before adding the next.</li>\n   <li>Front-load the structure: show the whole process once, then teach each part.</li>\n   <li>Interleave practice on earlier topics instead of blocking them into a single section.</li>\n </ul>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920118', '910108', 'Choosing Activities and Media', 'text', '<h3>Match the medium to the behaviour</h3>\n <p>If the objective is a decision, the activity should be a decision with feedback. Watching a video of someone deciding does not build the skill.</p>\n <p>Video earns its cost when movement, tone, or demonstration matters. Text wins for reference material that people will revisit.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920119', '910109', 'Aligning Assessments to Objectives', 'text', '<h3>Test what you taught</h3>\n <p>Every objective needs at least one assessment item that requires the learner to perform that objective, at the same cognitive level.</p>\n <p>Recall questions are legitimate for facts that must be memorised. They are not evidence of a skill objective. A quiz that asks which control is first in the hierarchy does not prove that someone can choose a control for a real hazard.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920120', '910109', 'Evaluating Course Impact', 'text', '<h3>Four levels, one honest question</h3>\n <p>Reaction tells you whether people liked it. Learning tells you whether they could do it at the end. Behaviour tells you whether they do it at work. Results tell you whether it mattered.</p>\n <p>Most organisations stop at the first. Pick one behaviour and one business measure before launch, and look at them ninety days later.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920121', '910110', 'The First Ten Minutes', 'text', '<h3>Attention is decided early</h3>\n <p>Start with the decision the participants will be able to make, not with the agenda slide. A room that knows why it is there will forgive a long session; a room that does not will check its phones.</p>\n <ul>\n   <li>Name the outcome in one sentence.</li>\n   <li>Ask a question the audience cannot answer yet. The gap creates attention.</li>\n   <li>State the rules: timing, questions, devices.</li>\n </ul>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920122', '910110', 'Setting Ground Rules Collaboratively', 'text', '<h3>Rules people wrote are rules people keep</h3>\n <p>Ask the room what would make the session useful, and write the answers down. Confidentiality, phones, and one conversation at a time usually come from the participants themselves.</p>\n <p>Add only what the group missed, and refer back to the list when behaviour slips. Enforcing a rule the room created takes one sentence. Enforcing a trainer rule takes an argument.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920123', '910111', 'Working With Quiet and Dominant Participants', 'text', '<h3>Two problems, one cause</h3>\n <p>Both silence and dominance come from unclear participation structures. Fix the structure, not the person.</p>\n <ul>\n   <li>Use written thinking time before discussion so quiet participants arrive with something to say.</li>\n   <li>Ask dominant participants to record or summarise instead of contributing again.</li>\n   <li>Direct questions to the group, then invite by name only after a pause.</li>\n </ul>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920124', '910111', 'Handling Challenging Questions', 'video', NULL, 'https://www.youtube.com/embed/1Y9d3lR6Qm4', '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920125', '910112', 'From Session to Workplace Action', 'text', '<h3>Close with a commitment</h3>\n <p>Ask each participant to write one action, the date, and the person who will notice. Then ask a few to read it aloud. Spoken commitments survive the week far better than good intentions.</p>\n <p>Finally, tell the room what follow-up they should expect from you. A session with a scheduled follow-up is a programme. A session without one is an event.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920126', '910113', 'What Counts as a Record', 'text', '<h3>Evidence, not everything</h3>\n <p>A record is information created or received in the course of business that serves as evidence of an activity or decision. Meeting minutes, approved leave forms, and signed contracts are records. A rough draft superseded by an approved version usually is not.</p>\n <p>Classify by consequence: what happens if this record is lost, or worse, disclosed? The answer determines how it is stored and who may open it.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920127', '910113', 'A Workable Naming Convention', 'text', '<h3>Dates, owner, type</h3>\n <p>Adopt one pattern and keep it: <code>YYYY-MM-DD_owner_doctype_version</code>. For example, <code>2026-10-14_LD_retention-schedule_v3</code>.</p>\n <ul>\n   <li>Lead with the date so folders sort chronologically.</li>\n   <li>No spaces, no final, no copy, no latest.</li>\n   <li>Version numbers for working documents, dates for approved ones.</li>\n </ul>\n <p>A convention people actually follow beats a perfect taxonomy nobody uses.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920128', '910114', 'Reading a Retention Schedule', 'text', '<h3>Three columns that matter</h3>\n <p>Every schedule names the record series, the retention period, and the trigger event that starts the clock. The trigger is where most errors happen: it is rarely the creation date.</p>\n <ul>\n   <li>Employee records: often retained for a fixed period after separation, not after hiring.</li>\n   <li>Financial records: usually tied to the close of the fiscal year.</li>\n   <li>Training records: typically tied to the certification expiry.</li>\n </ul>\n <p>When two schedules overlap, keep the longer period and document why.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920129', '910114', 'Secure Disposal and Audit Trails', 'text', '<h3>Deletion needs evidence</h3>\n <p>Deleting a file is not disposal. Paper needs cross-cut shredding, drives need wiping or physical destruction, and shared drives need the copy in the deleted items folder removed too.</p>\n <p>Log what was destroyed, when, by whom, and under which schedule entry. During an audit, the log is the deliverable, not the empty cabinet.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920130', '910115', 'Stress, Burnout, and Distress', 'text', '<h3>Know the difference before you respond</h3>\n <p>Stress is a reaction to pressure and usually eases when the pressure does. Burnout is exhaustion that follows prolonged demand and does not lift after a weekend. Distress is significant emotional pain that interferes with daily functioning.</p>\n <p>You are not diagnosing anyone. The distinction matters because it changes what you offer: workload adjustment, time off, or urgent professional support.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920131', '910115', 'What the Law Expects of Employers', 'text', '<h3>Duty of care, in plain terms</h3>\n <p>Employers are expected to provide a safe working environment, which includes psychosocial hazards: excessive workload, unclear expectations, bullying, and prolonged uncertainty.</p>\n <p>That means risk assessment, reasonable adjustments for a person returning from leave, and confidential handling of health information. It does not mean the employer provides treatment. It means the employer does not add harm.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920132', '910116', 'Opening a Supportive Conversation', 'text', '<h3>Observe, do not interpret</h3>\n <p>Start with what you noticed, then hand the conversation over. For example: I noticed you have been quiet in the last three team meetings, and I wanted to check how you are doing.</p>\n <ul>\n   <li>Ask twice. The first answer is usually fine, thanks.</li>\n   <li>Listen without filling the silence.</li>\n   <li>Do not promise confidentiality you cannot keep.</li>\n </ul>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920133', '910116', 'Referring to Professional Support', 'text', '<h3>Hand over, do not advise</h3>\n <p>Know the referral routes before you need them: employee assistance programme, occupational health, clinic, or emergency services for immediate risk.</p>\n <p>If someone expresses intent to harm themselves, stay with them, remove access to means where possible, and contact emergency support. Do not leave them alone to follow up tomorrow.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920134', '910117', 'The Cost of Poor Communication', 'text', '<h3>Silence fills itself</h3>\n <p>When leadership does not explain a change, people invent an explanation. The invented version is usually worse, and it spreads faster than any official memo.</p>\n <p>Communicate the decision, the reason, the timeline, and what is still undecided. Naming the undecided parts is what makes the rest believable.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920135', '910117', 'Stakeholder Mapping', 'text', '<h3>Who can stop this change?</h3>\n <p>List everyone affected, then mark two things: how much the change affects them, and how much influence they have over whether it happens.</p>\n <p>The high-influence, high-impact group needs conversation, not email. The low-impact, high-influence group needs information early so they are not surprised. Everyone else needs clarity on what changes for them personally.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920136', '910118', 'The ADKAR Journey', 'text', '<h3>Five conditions, in order</h3>\n <ol>\n   <li><strong>Awareness</strong> of why the change is needed.</li>\n   <li><strong>Desire</strong> to support it.</li>\n   <li><strong>Knowledge</strong> of how to change.</li>\n   <li><strong>Ability</strong> to perform in the new way.</li>\n   <li><strong>Reinforcement</strong> that keeps it in place.</li>\n </ol>\n <p>Most failed initiatives skip straight to knowledge with a training session. If awareness and desire are missing, the training produces people who know what to do and do not do it.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920137', '910118', 'Sustaining the Change', 'text', '<h3>Make the old way harder</h3>\n <p>New behaviour persists when it is easier than the old behaviour, visible, and rewarded. Update the forms, remove the legacy shortcut, and report the new measure publicly for at least two cycles.</p>\n <p>Also plan for the moment enthusiasm drops, usually six to eight weeks in. Decide now what the follow-up check will be, and who owns it.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920138', '910119', 'Connecting and Cleaning HR Exports', 'text', '<h3>Garbage in, confident dashboards out</h3>\n <p>HR exports arrive with merged headers, blank rows, and duplicated employee numbers. Clean once in Power Query so the transformation is repeatable, not manually every month.</p>\n <ul>\n   <li>Promote headers and set data types explicitly.</li>\n   <li>Remove duplicates on employee number, then check the row count against the source.</li>\n   <li>Normalise department names before building anything.</li>\n </ul>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920139', '910119', 'Building a Simple Data Model', 'text', '<h3>One fact table, few dimensions</h3>\n <p>Keep a central table of events, such as enrollments or hires, and separate tables for employee, department, and date. Relationships should be one-to-many, single direction.</p>\n <p>A star model of five tables is enough for almost every HR question. Complexity arrives when someone joins two fact tables directly, and the totals double without warning.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920140', '910120', 'Choosing the Right Visual', 'text', '<h3>Answer a question, not decorate a page</h3>\n <ul>\n   <li>Comparison across categories: bar chart, sorted by value.</li>\n   <li>Trend over time: line chart with a clear date axis.</li>\n   <li>Composition: stacked bar, or a single number if it is one number.</li>\n   <li>Distribution: histogram, not a pie chart of ten slices.</li>\n </ul>\n <p>If a visual needs a paragraph to explain it, the visual is the wrong choice.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920141', '910120', 'Publishing and Sharing Responsibly', 'text', '<h3>Dashboards leak too</h3>\n <p>Row-level security, workspace permissions, and a review of every field on the page. A dashboard that exposes individual salaries to a department head is a privacy incident with a nice colour scheme.</p>\n <p>Publish with a named owner, a refresh schedule, and a note on the source of record. Unattributed numbers get argued about instead of used.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920142', '910121', 'Diagnosing the Real Issue', 'text', '<h3>The presenting complaint is rarely the problem</h3>\n <p>Two colleagues who cannot work together may have a resource conflict, an unclear decision right, or a history that predates the current project. The intervention differs for each.</p>\n <p>Ask separately: what happened, what did you expect, and what would need to change for this to work. Compare the answers before you convene anyone.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920143', '910121', 'Preparing Your Opening Line', 'text', '<h3>Facts first, no verdict</h3>\n <p>Open with the observation and the intention, and leave the conclusion out. For example: I want to sort out the handover gap between your two teams. Last week two requests sat for four days.</p>\n <p>An opening that assigns blame guarantees defence. An opening that describes an event invites explanation.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920144', '910122', 'Staying Calm Under Pressure', 'text', '<h3>Lower the temperature, keep the substance</h3>\n <ul>\n   <li>Slow down rather than raise volume.</li>\n   <li>Name the emotion once, then return to the issue.</li>\n   <li>If it escalates, pause the meeting and reschedule with a neutral party.</li>\n </ul>\n <p>You do not need to win the exchange. You need a workable agreement by the end of the week.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920145', '910122', 'Turning Agreement into Action', 'text', '<h3>Write it down in the room</h3>\n <p>End by summarising what each person will do, by when, and how it will be reviewed. Send the summary the same day and ask for corrections within 48 hours.</p>\n <p>An agreement that exists only in memory gets renegotiated the moment it becomes inconvenient.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920146', '910123', 'What Professional Conduct Looks Like', 'text', '<h3>Behaviour, not intention</h3>\n <p>The code of conduct describes how work is done here: honesty in reporting, respect in disagreement, care with institutional property, and discretion with information.</p>\n <p>Read it as a set of observable behaviours. Punctuality in commitments, accuracy in records, and courtesy in a disagreement are all visible, and all reviewable.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920147', '910123', 'Conflicts of Interest and Gifts', 'text', '<h3>Declare early, in writing</h3>\n <p>A conflict of interest is not misconduct. Concealing one is.</p>\n <ul>\n   <li>Declare any relationship that could influence a hiring, procurement, or grading decision.</li>\n   <li>Declare any gift or hospitality beyond token value, before accepting it.</li>\n   <li>Withdraw from the decision, not just from the conversation about it.</li>\n </ul>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920148', '910124', 'Recognising Harassment', 'text', '<h3>Unwelcome, and about a protected characteristic</h3>\n <p>Harassment is unwelcome conduct that creates an intimidating, hostile, or offensive environment. It can be a single serious act or a pattern of smaller ones. Intent does not determine whether it happened.</p>\n <p>It includes comments about appearance, jokes about a protected group, repeated exclusion, and persistent contact after a clear no.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920149', '910124', 'Reporting and Non-Retaliation', 'text', '<h3>Channels and protection</h3>\n <p>Reports may go to a line manager, HR, or the designated committee, in writing or verbally. A report should be acknowledged and investigated under the published procedure.</p>\n <p>Retaliation against a reporter or a witness is itself a disciplinary matter, regardless of whether the original complaint is upheld. Protection begins at the moment of the report.</p>', NULL, '2', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
INSERT INTO `ld_lesson` (`id`, `module_id`, `title`, `content_type`, `content_body`, `video_url`, `order_index`, `status`, `created_at`, `updated_at`) VALUES ('920150', '910125', 'Where AI Helps and Where It Does Not', 'text', '<h3>Draft content</h3>\n <p>Assistants are useful for first drafts, summarising long documents, and reformatting structured text. They are unreliable for current facts, calculations you cannot check, and anything requiring accountability.</p>\n <p>Never paste student records, employee data, or unpublished financials into a public tool. Check every output against the source before it leaves your screen.</p>', NULL, '1', 'active', '2026-10-25 01:02:36', '2026-10-25 01:02:36');
